import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
a = [[int(data[2 + i * c + j]) for j in range(c)] for i in range(r)]
i = j = 0
up = True
out = []
for _ in range(r * c):
    out.append(a[i][j])
    if up:
        if j == c - 1:
            i += 1
            up = False
        elif i == 0:
            j += 1
            up = False
        else:
            i -= 1
            j += 1
    else:
        if i == r - 1:
            j += 1
            up = True
        elif j == 0:
            i += 1
            up = True
        else:
            i += 1
            j -= 1
print(' '.join(map(str, out)))

